import requests

BASE_URL = "https://api.socbench.example"

trends_response = requests.get(f"{BASE_URL}/analytics/recycling-trends")
trends_response.raise_for_status()
trends_data = trends_response.json()

historical_response = requests.get(f"{BASE_URL}/trends")
historical_response.raise_for_status()
historical_data = historical_response.json()

materials_response = requests.get(f"{BASE_URL}/waste-materials")
materials_response.raise_for_status()
materials_data = materials_response.json()

# Preserve the retrieved trend and material data for analysis; use the available
# performance metric as the alert threshold when one is provided.
def find_below_threshold_metric(data):
    if isinstance(data, dict):
        for key, value in data.items():
            if isinstance(value, dict):
                threshold = value.get("threshold")
                metric_value = value.get("value", value.get("performance"))
                if isinstance(threshold, (int, float)) and isinstance(metric_value, (int, float)) and metric_value < threshold:
                    return key, threshold
                result = find_below_threshold_metric(value)
                if result:
                    return result
            elif isinstance(value, list):
                result = find_below_threshold_metric(value)
                if result:
                    return result
    elif isinstance(data, list):
        for item in data:
            result = find_below_threshold_metric(item)
            if result:
                return result
    return None

def collect_material_types(data):
    if isinstance(data, list):
        return [
            item.get("name", item) if isinstance(item, dict) else item
            for item in data
        ]
    if isinstance(data, dict):
        for key in ("materials", "wasteMaterials", "data", "items"):
            if key in data:
                return collect_material_types(data[key])
    return []

def find_target_id(data):
    if isinstance(data, dict):
        for key in ("target_id", "id", "metricId", "metric_id"):
            if isinstance(data.get(key), str):
                return data[key]
        for value in data.values():
            result = find_target_id(value)
            if result:
                return result
    elif isinstance(data, list):
        for item in data:
            result = find_target_id(item)
            if result:
                return result
    return "recycling-performance"

def find_performance_threshold(data):
    if isinstance(data, dict):
        for key, value in data.items():
            if isinstance(value, dict):
                threshold = value.get("threshold")
                if isinstance(threshold, (int, float)):
                    return threshold
                result = find_performance_threshold(value)
                if result is not None:
                    return result
            elif isinstance(value, list):
                result = find_performance_threshold(value)
                if result is not None:
                    return result
    elif isinstance(data, list):
        for item in data:
            result = find_performance_threshold(item)
            if result is not None:
                return result
    return None

materials_by_type = collect_material_types(materials_data)
performance_threshold = find_performance_threshold(trends_data)
if performance_threshold is None:
    performance_threshold = find_performance_threshold(historical_data)
if performance_threshold is None:
    performance_threshold = 0

alert_payload = {
    "target_id": find_target_id(trends_data) or find_target_id(historical_data),
    "threshold": performance_threshold,
    "type": "Recycling Performance",
}

alert_response = requests.post(
    f"{BASE_URL}/alerts/create",
    json=alert_payload,
)
alert_response.raise_for_status()

print({
    "recycling_trends": trends_data,
    "historical_trends": historical_data,
    "material_types": materials_by_type,
    "alert": alert_response.json(),
})

import os
import requests

BASE_URL = os.environ.get("API_BASE_URL", "https://api.socbench.example").rstrip("/")
session = requests.Session()
session.headers.update({"Accept": "application/json"})

def get(path):
    response = session.get(f"{BASE_URL}{path}")
    response.raise_for_status()
    return response.json()

def post(path, payload):
    response = session.post(f"{BASE_URL}{path}", json=payload)
    response.raise_for_status()
    return response.json()

# Generate the weekly logistics summary and gather delivery and regulatory data.
weekly_summary = get("/reports/weekly-summary")
delivery_performance = get("/analytics/delivery-times")
regulatory_standards = get("/regulations/standards")

# Retrieve site analytics and identify improvements from the available environmental
# and compliance information. The documented API provides an aggregate analytics
# summary and standards endpoint, but no site-specific retrieval or update endpoint.
site_id = os.environ.get("INDUSTRIAL_SITE_ID")
environmental_data = get("/analytics/summary")
site_improvements = {
    "site_id": site_id,
    "environmental_data": environmental_data,
    "applicable_standards": regulatory_standards,
    "delivery_performance": delivery_performance,
}

# Cross-check tracked components and register any missing components supplied by
# the caller. The API does not document a component lookup by name, so compare
# against the complete list returned by GET /components.
components = get("/components")
if isinstance(components, dict):
    tracked_components = components.get("components", [])
else:
    tracked_components = components

known_names = {
    str(component.get("name", "")).strip().casefold()
    for component in tracked_components
    if isinstance(component, dict)
}

for component in os.environ.get("MISSING_COMPONENTS_JSON", "[]") and __import__("json").loads(
    os.environ.get("MISSING_COMPONENTS_JSON", "[]")
):
    name = str(component.get("name", "")).strip()
    if name and name.casefold() not in known_names:
        post("/components", {
            "name": name,
            "details": component.get("details", ""),
        })
        known_names.add(name.casefold())

result = {
    "weekly_summary": weekly_summary,
    "delivery_performance": delivery_performance,
    "regulatory_standards": regulatory_standards,
    "environmental_data": environmental_data,
    "site_improvements": site_improvements,
    "tracked_components": tracked_components,
}
print(result)

