import requests

BASE_URL = "https://api.socbench.example"
API_KEY = "YOUR_API_KEY"

headers = {"X-API-Key": API_KEY}

# Retrieve alerts and retain their detailed information indexed by alert ID.
alerts_response = requests.get(f"{BASE_URL}/alerts", timeout=30)
alerts_response.raise_for_status()
alerts = alerts_response.json()
alerts_by_id = {
    alert["alertID"]: alert
    for alert in alerts
    if isinstance(alert, dict) and "alertID" in alert
}

# Retrieve available channels for potential broadcasting.
channels_response = requests.get(
    f"{BASE_URL}/content-distribution",
    headers=headers,
    timeout=30,
)
channels_response.raise_for_status()
channels = channels_response.json()

# Retrieve current latency and available regions' metrics. The documented API
# provides region metrics by ID but does not provide a region-list endpoint.
latency_response = requests.get(f"{BASE_URL}/metrics/latency", timeout=30)
latency_response.raise_for_status()
current_latency = latency_response.json()

# Use region IDs discovered in channel data to obtain regional performance metrics.
region_ids = sorted(
    {
        channel["region"]
        for channel in channels
        if isinstance(channel, dict) and channel.get("region")
    }
)
regional_metrics = {}
for region_id in region_ids:
    response = requests.get(
        f"{BASE_URL}/regions/{region_id}/metrics",
        timeout=30,
    )
    if response.ok:
        regional_metrics[region_id] = response.json()

# Generate data-driven insights from the available latency and channel data.
def latency_ms(value):
    if not isinstance(value, str):
        return None
    try:
        return float(value.strip().lower().removesuffix("ms").strip())
    except ValueError:
        return None


regional_latencies = {
    region_id: latency_ms(metrics.get("latency"))
    for region_id, metrics in regional_metrics.items()
}
regional_latencies = {
    region_id: value
    for region_id, value in regional_latencies.items()
    if value is not None
}

insights = {
    "current_latency": current_latency,
    "regional_metrics": regional_metrics,
    "alerts_by_id": alerts_by_id,
    "suitable_channels": channels,
    "recommendations": [],
}

if regional_latencies:
    highest_latency_region = max(regional_latencies, key=regional_latencies.get)
    lowest_latency_region = min(regional_latencies, key=regional_latencies.get)
    insights["recommendations"].append(
        f"Prioritize latency investigation and capacity optimization in region "
        f"{highest_latency_region} ({regional_latencies[highest_latency_region]} ms); "
        f"consider routing latency-sensitive broadcasts through region "
        f"{lowest_latency_region} ({regional_latencies[lowest_latency_region]} ms) "
        f"where channel availability permits."
    )
else:
    current_ms = latency_ms(current_latency.get("latency"))
    if current_ms is not None:
        insights["recommendations"].append(
            f"Current network latency is {current_ms} ms. Compare this baseline "
            "with future regional measurements to identify latency trends."
        )
    else:
        insights["recommendations"].append(
            "Regional latency measurements were unavailable; collect regional "
            "metrics over time before drawing trend conclusions."
        )

if channels:
    channel_regions = sorted(
        {
            channel.get("region")
            for channel in channels
            if isinstance(channel, dict) and channel.get("region")
        }
    )
    insights["recommendations"].append(
        f"Evaluate the {len(channels)} matching distribution channel(s) for "
        f"broadcasting; available channel regions: {', '.join(channel_regions) or 'unspecified'}."
    )
else:
    insights["recommendations"].append(
        "No matching distribution channels were returned; broaden channel criteria "
        "or verify channel availability before scheduling a broadcast."
    )

print(insights)

