BASE_URL = "https://api.socbench.example"

grid_id = "grid-123"
asset_id = "asset-456"

optimization_parameters = {
    "assetId": asset_id,
    "objective": "load_balancing",
    "constraints": {
        "preserve_asset_operational_limits": True
    }
}

optimization_response = requests.post(
    f"{BASE_URL}/optimizations",
    json={
        "gridId": grid_id,
        "parameters": optimization_parameters
    }
)
optimization_response.raise_for_status()

# No documented endpoint retrieves an individual asset's operational status.
# Request a custom forecast to provide energy production data for the strategy.
forecast_response = requests.post(
    f"{BASE_URL}/energy/forecast/request",
    json={
        "energy_type": "solar",
        "parameters": {
            "gridId": grid_id,
            "assetId": asset_id,
            "start_date": "2026-11-03",
            "end_date": "2026-11-10"
        }
    }
)
forecast_response.raise_for_status()

