import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()
session.headers.update({"Content-Type": "application/json"})

transaction_response = session.post(
    f"{BASE_URL}/transactions",
    json={
        "propertyId": "property-123",
        "buyer": "Buyer Name",
        "seller": "Seller Name",
        "details": "Purchase transaction for property-123",
    },
)
transaction_response.raise_for_status()
transaction = transaction_response.json()
transaction_id = transaction.get("id") or transaction.get("transactionId")
if not transaction_id:
    raise ValueError("Transaction response did not include an ID")

report_response = session.post(
    f"{BASE_URL}/custom-reports",
    json={
        "criteria": {
            "region": "specified-region",
            "property_type": "residential",
        },
        "preferences": {
            "include_market_analysis": True,
            "include_recent_sales": True,
        },
    },
)
report_response.raise_for_status()

feedback_response = session.post(
    f"{BASE_URL}/tours/property-123/feedback",
    json={
        "rating": 5,
        "comments": "The tour was informative and easy to navigate.",
    },
)
feedback_response.raise_for_status()

finalize_response = session.post(
    f"{BASE_URL}/transactions/{transaction_id}/finalize"
)
finalize_response.raise_for_status()
